<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowLeft, ArrowUpRight, BookOpen, Check, Clock3, Download, Layers3 } from 'lucide-vue-next'
import { api, dateText, errorText, kindNames, type CourseDetail } from '../api'
const route = useRoute(), course = ref<CourseDetail | null>(null), error = ref(''), loading = ref(true)
const group = ref(''), chapter = ref('')
const shown = computed(() => course.value?.lessons.filter(l => (!group.value || l.group_id === group.value) && (!chapter.value || l.chapter_ids.includes(chapter.value))) || [])
let request = 0
async function load() {
  const id = ++request
  loading.value = true; error.value = ''; group.value = ''; chapter.value = ''
  try { const result = await api<CourseDetail>(`/courses/${encodeURIComponent(String(route.params.slug))}`); if (id === request) course.value = result }
  catch (e) { if (id === request) error.value = errorText(e) }
  finally { if (id === request) loading.value = false }
}
watch(() => route.params.slug, load, { immediate: true })
</script>
<template>
  <RouterLink to="/catalog" class="back-link"><ArrowLeft :size="16" />返回课程目录</RouterLink>
  <div v-if="loading" class="loading-panel" role="status">正在打开这门课程…</div>
  <div v-else-if="error" class="empty-state"><h1>暂时无法打开课程</h1><p role="alert">{{ error }}</p><button class="button secondary" @click="load">重试</button></div>
  <template v-else-if="course"><section class="detail-hero"><div><div class="card-tags"><span v-for="tag in course.tags" :key="tag">{{ tag }}</span></div><h1>{{ course.title }}</h1><p>{{ course.summary }}</p><div class="detail-meta"><span><Layers3 :size="16" />{{ course.counts.lesson_count }} 个课时</span><span><BookOpen :size="16" />{{ course.counts.chapter_count }} 个章节</span><span><Clock3 :size="16" />{{ course.counts.lessons_without_duration ? '自主安排节奏' : '约 ' + course.counts.known_duration_minutes + ' 分钟' }}</span></div><a :href="course.launch_url" class="button primary">开始探索 <ArrowUpRight :size="18" /></a></div><img :src="course.cover.url" :alt="course.cover.alt"></section>
  <div class="detail-layout"><div><section class="detail-section"><p class="eyebrow">ABOUT THIS COURSE</p><h2>这门课，带你走近什么</h2><p class="description-text">{{ course.description }}</p></section><section class="detail-section"><div class="section-heading"><div><p class="eyebrow">YOUR LEARNING PATH</p><h2>课程内容</h2></div><span class="muted small-text">{{ course.counts.lesson_count }} 个已发布 · {{ course.counts.planned_lesson_count }} 个计划中</span></div><div class="tag-filters lesson-tabs"><button :class="{ active: !group }" @click="group = ''">全部课时</button><button v-for="item in course.groups" :key="item.id" :class="{ active: group === item.id }" @click="group = item.id">{{ item.title }}</button></div><div v-if="chapter" class="filter-indicator">正在查看：{{ course.chapters.find(c => c.id === chapter)?.title }}<button class="text-button" @click="chapter = ''">显示全部章节</button></div><div class="detail-lesson-list"><component :is="lesson.url ? 'a' : 'div'" v-for="(lesson, i) in shown" :key="lesson.id" :href="lesson.url || undefined" class="detail-lesson" :class="{ planned: !lesson.url }"><span class="lesson-number">{{ String(i + 1).padStart(2, '0') }}</span><div><span class="overline">{{ kindNames[lesson.kind] }}<span v-if="lesson.duration_minutes"> · {{ lesson.duration_minutes }} 分钟</span></span><h3>{{ lesson.title }}</h3><p>{{ lesson.summary }}</p></div><ArrowUpRight v-if="lesson.url" :size="20" /><span v-else class="badge neutral">计划中</span></component><p v-if="!shown.length" class="empty-inline">当前筛选下还没有课时。</p></div></section><section v-if="course.resources.length" class="detail-section"><p class="eyebrow">TAKE IT FURTHER</p><h2>把探索带走</h2><a v-for="resource in course.resources" :key="resource.id" :href="resource.url" class="resource-link" download><span><Download :size="18" />{{ resource.title }}</span><ArrowUpRight :size="17" /></a></section><section v-if="course.gallery.length" class="detail-section"><h2>课程预览</h2><img v-for="image in course.gallery" :key="image.url" :src="image.url" :alt="image.alt" class="gallery-image" loading="lazy"></section></div>
  <aside class="detail-sidebar"><section class="info-card"><p class="eyebrow">THE PEOPLE BEHIND IT</p><h3>课程制作</h3><div v-for="creator in course.creators" :key="creator.id" class="creator-info"><img v-if="creator.avatar" :src="creator.avatar.url" :alt="creator.avatar.alt" class="avatar"><span v-else class="avatar">{{ creator.name.slice(0, 1) }}</span><div><strong>{{ creator.name }}</strong><p>{{ [creator.organization, creator.team].filter(Boolean).join(' · ') }}</p><span class="small-text muted">{{ creator.roles.map(r => ({ author: '制作', instructor: '授课', editor: '编辑', reviewer: '审校' }[r] || r)).join(' / ') }}</span></div></div><p class="small-text muted">{{ course.creators[0]?.bio }}</p></section><section v-if="course.chapters.length" class="info-card"><p class="eyebrow">THE BIG PICTURE</p><h3>章节地图</h3><button v-for="(item, i) in course.chapters" :key="item.id" class="chapter-button" :class="{ selected: chapter === item.id, subsection: item.parent_id }" @click="chapter = chapter === item.id ? '' : item.id"><span>{{ String(i + 1).padStart(2, '0') }}</span>{{ item.title }}<Check v-if="chapter === item.id" :size="15" /></button></section><p class="detail-updated">最近发布于 {{ dateText(course.published_at) }}<br>以自己的节奏，慢慢理解。</p></aside></div></template>
</template>
